"""Publish audited outcomes, unsuccessful hypotheses and precise pilot boundaries."""
import html,statistics
from datetime import datetime,timezone
from v6_support import ROOT,HERE,BASE,DOCS,read,write,sha,fit_record
def table(headers,rows):
    return '<table><thead><tr>'+''.join('<th>'+html.escape(str(x))+'</th>'for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>'for x in row)+'</tr>'for row in rows)+'</tbody></table>'
def build():
    completion=read(DOCS/'completion-audit.json');audit=read(DOCS/'final-audit.json')
    if completion['status']!='complete'or audit['status']!='passed':raise ValueError('Current complete five-track evidence required')
    evidence={}
    def data(p):evidence[str(p.relative_to(ROOT))]=sha(p);return read(p)
    selection=data(DOCS/'selection.json');pre=data(DOCS/'preselection.json');points=data(DOCS/'calibration-points-03.json')['points'];fits=[]
    for arm in data(DOCS/'campaign.json')['fits']:
        r=fit_record(arm);p=ROOT/r['project'];s=ROOT/r['study'];receipt=data(s/'receipt.json');history=data(s/'train/history.json');spec=data(p/'fine-tuning.json');work=history['optimizer_work']
        fits.append(dict(identifier=arm,parameters=spec['parameters'],solver_training_iterations=spec['solver_training_iterations'],updates=receipt['optimizer_updates'],network_forwards=work['network_forwards'],forward_cells=work['forward_cells'],
          training_seconds=history['training_finished_unix']-history['training_started_unix'],exact_cpu_restore=all(receipt['artifact_parity'].values()),project=r['project'],study=r['study']))
    timing=[data(BASE/'quiet-development'/(p['identifier']+'.json'))for p in points];blind=[data(BASE/'blind-evaluation'/(p['identifier']+'.json'))for p in selection['blind_points']]
    reservation=data(DOCS/'timing-reservation.json');native=[];breakdown=[]
    for row in reservation['rows']:
        for method in reservation['methods']:
            ds=[data(BASE/'quiet-native'/(row['trajectory_id']+'-'+method['label']+f'-r{repeat}')/'receipt.json')for repeat in range(3)]
            medians=[statistics.median(f['frame_seconds']for f in d['frames'])for d in ds]
            native.append(dict(counts=row['scene']['counts'],steps=row['scene']['steps'],method=method['label'],point=method['point'],completed_repeats=sum(d['status']=='completed'for d in ds),repeats=3,
              median_seconds=statistics.median(medians),min_seconds=min(medians),max_seconds=max(medians),
              total_global_calls=sum(sum(c['work']['coarse_calls']for c in d['callbacks'])for d in ds),global_call_kind='direct_spectral_solve'if method['point']['method']=='spectral'else'hierarchy_cycle',
              adaptive_admissions=sum(sum(bool(c['work'].get('adaptive_reuse')and c['work']['adaptive_reuse']['admitted'])for c in d['callbacks'])for d in ds)))
            if method['label']=='selected-fresh':
                frames=[f for d in ds for f in d['frames']];calls=[c for d in ds for c in d['callbacks']]
                total=sum(f['frame_seconds']for f in frames);nn=sum(c['work']['network_seconds']for c in calls)
                breakdown.append(dict(counts=row['scene']['counts'],complete=all(d['status']=='completed'for d in ds),total_frame_seconds=total,total_network_seconds=nn,network_fraction=nn/total,
                  median_preparation_seconds=statistics.median(f['preparation_seconds']for f in frames),median_pressure_seconds=statistics.median(f['pressure_seconds']for f in frames),
                  median_projection_seconds=statistics.median(f['projection_seconds']for f in frames),median_callback_seconds=statistics.median(c['method_seconds']for c in calls),
                  median_network_seconds=statistics.median(c['work']['network_seconds']for c in calls),median_coarse_seconds=statistics.median(c['work']['coarse_seconds']for c in calls)))
    drift=[data(p)for p in sorted((BASE/'long-drift').glob('*.json'))];cal=data(DOCS/'reuse-calibration.json');sections=[];findings=[]
    for counts in [[64]*3,[128]*3,[256]*3]:
        group={r['method']:r for r in native if r['counts']==counts and r['completed_repeats']==3}
        if 'selected-fresh'in group and 'baseline-v5'in group:
            old=group['baseline-v5']['median_seconds'];new=group['selected-fresh']['median_seconds'];change=100*(1-new/old)
            findings.append('On '+html.escape('×'.join(map(str,counts)))+' cells, the selected fresh policy took '+f'{new:.3f}'+' s per fluid step versus '+f'{old:.3f}'+' s for the previous tiny policy ('+f'{abs(change):.1f}'+('% lower'if change>=0 else'% higher')+').')
    sections.append('<h2>Measured outcomes</h2><p>'+' '.join(findings)+'</p>')
    controls=[]
    for counts in [[64]*3,[128]*3,[256]*3]:
        group={r['method']:r for r in native if r['counts']==counts and r['completed_repeats']==3}
        if all(k in group for k in ['selected-fresh','numerical','spectral']):
            controls.append('At '+'×'.join(map(str,counts))+' cells, selected / numerical / spectral times are '+ ' / '.join(f"{group[k]['median_seconds']:.3f}"for k in ['selected-fresh','numerical','spectral'])+' seconds per fluid step.')
    sections.append('<p>'+html.escape(' '.join(controls))+'</p>')
    sections.append('<p>All four fitted contrasts and their fresh CPU restores completed. Every original development request remains visible. The spectral method and the best development-qualified iterative numerical control are retained as strong comparisons; improving the neural policy does not establish superiority over those controls. This study does not promote an application model.</p>')
    sections.append('<h2>Training contrasts and actual work</h2><p>The replay and three-iteration arms start from the same completed v5 post-coarse checkpoint. The stencil has 27 learned coefficients; the separable model has three axis filters with nine coefficients. Every model has a fixed q/8 skip, replicated boundaries, fixed original train-only normalization, 2,400 updates and the same original 1,600-small-sample stream plus 800 larger-tier selections. Actual forward work differs for multi-iteration training. All models use the same original 34-parent native bank; no new v6 scene enters training.</p>'+table(['Model','Parameters','Training iterations','Updates','Actual NN forwards','Forward cells','Training seconds','Exact fresh CPU restore'],[[r[k]for k in ['identifier','parameters','solver_training_iterations','updates','network_forwards','forward_cells']]+[f"{r['training_seconds']:.1f}",r['exact_cpu_restore']]for r in fits]))
    failed=data(BASE/'failed-unrolled-attempt-01/summary.json');amendment=data(BASE/'adjoint-execution-amendment-01.json');parity=data(BASE/'adjoint-objective-parity-01.json')
    sections.append('<h2>Preserved time-limit failure and equivalent adjoint</h2><p>The first three-iteration attempt failed and drained at its original 1,800-second ceiling after reporting at least '+str(failed['minimum_completed_updates'])+' updates. Its exact final partial update count was not published, and it is excluded from successful-fit counts. The successful second execution keeps the same configuration, initial tensors, sampling and 1,800-second ceiling. It uses the qualified direct fine operator and the exact symmetric-cycle transpose, including the cell-zero gauge transpose. No coarse-stage gradient is discarded. Dense transpose, finite-difference, original-autograd and full-128³ tests check the derivative. The complete three-step objective differs by at most '+f"{max(r['loss_relative_difference']for r in parity['rows']):.3g}"+' relatively and all 648 parameter gradients by '+f"{max(r['all_parameter_gradient_relative_difference']for r in parity['rows']):.3g}"+'. These are numerical equivalence checks; the observed training durations are not repeated isolated throughput benchmarks. <a href="../../../runs/pressure-methods-v6/failed-unrolled-attempt-01/summary.json">Discarded attempt</a> · <a href="../../../runs/pressure-methods-v6/adjoint-execution-amendment-01.json">Captured amendment</a>.</p>')
    development=[]
    for p in points:
        d=data(BASE/'development'/(p['identifier']+'.json'));development.append([p['identifier'],f"{d['qualified']}/{d['cases']}",d['median_coarse_calls'],d['median_network_calls'],f"{d['worst_pressure_relative_l2']:.3g}"])
    sections.append('<h2>Complete consumed-data development</h2><p>Nineteen configurations see the same 254 requests: 192 retained prior requests plus ten native and eighteen spatial v5 development requests, and ten native and twenty-four spatial v5 blind requests that are now consumed development. No v6 blind data is used here. Both unchanged physical gates apply to the actual returned float64 pressure. Conditional policies with no observed CNN calls remain reported but cannot substitute for an actively used learned model in the long/larger-grid model tests.</p>'+table(['Policy','Qualified','Median global calls','Median CNN calls','Worst pressure relative L2'],development))
    sections.append('<p>In the work-count tables, the spectral row records direct spectral solves; other rows record hierarchy cycles. The common counter is not a unit of equal computational cost. Repeated wall-clock comparisons remain the basis for speed claims.</p>')
    sections.append('<p>The fixed q/8 numerical control exactly isolates the learned graph’s skip with the same f32 conversion and zero learned convolutions. Its zero-parameter and full-256³ equivalence checks, and a real 32-step native episode, are retained. This separates benefits from learned filtering from benefits of adding an inexpensive numerical smoother. The coarser-placement probe directly observes 32³ CNN inputs on a native 64³ request; fewer neural cells alone do not establish a lower complete solve cost. The 0.25 stagnation trigger did not invoke the CNN on any of the 254 consumed requests. A deliberately weakened-global-stage test exercises its dispatch branch without claiming a naturally stalled-flow benefit.</p>')
    sections.append('<h2>Repeated matched pressure-policy timing</h2><p>Twenty consumed native cold/warm requests from ten forcing scenes on 32³–128³ and rectangular grids. CPU 23, one thread, a complete population warmup and three timed repeats per request. Loading, setup and labels are excluded. Every correction, conversion, operator, stopping decision and common independent returned-field gate counts. No correction directions carry between independent requests. Both passing coverage and error are shown; an attempted rejected point cannot enter a qualified frontier.</p>'+table(['Policy','Parameters','Qualified','Median ms','Worst pressure relative L2','Median CNN calls'],[[d['identifier'],d['parameters'],f"{d['summary']['qualified']}/{d['summary']['cases']}",f"{d['summary']['median_ms']:.3f}",f"{d['summary']['worst_pressure_relative_l2']:.3g}",d['summary']['median_network_calls']]for d in timing]))
    sections.append('<h2>Frozen selection and correction reuse</h2><p>The selected actively used learned configurations are '+', '.join(html.escape(r['point']['identifier'])for r in selection['selected'])+'. The primary numerical comparison is '+html.escape(selection['numerical_primary']['identifier'])+'. Selection uses consumed development coverage, repeated pressure-policy time and error. No refit or reselection follows the new blind results. Exact model entries and source fingerprints are in <a href="selection.json">the frozen selection</a>.</p><p>The first four-cycle heuristic never admitted reuse on the mostly three-cycle development solves; its results remain retained. The final rule uses measured development costs and actual fresh-work estimates. It admits only when predicted savings exceed measured projection/maintenance overhead by 15% and the residual sketch cosine is at least 0.9. A rejected host step commits neither directions nor decision history. Coefficient retention avoids full pressure-norm scoring and copies; stored direction/image tensors remain immutable. Four pairs use 16 MiB at 64³, 128 MiB at 128³ and 1 GiB at 256³, beyond ordinary solver workspace. Calibration extrapolation is a hypothesis, not a guarantee of runtime benefit.</p>'+table(['Calibration grid','Steps','Fresh total cycles','Cached total cycles','Estimated saved fraction','Baseline cycles'],[['×'.join(map(str,b['counts_xyz'])),b['steps'],b['fresh_total_cycles'],b['cached_total_cycles'],f"{b['saved_fraction']:.3f}",b['baseline_iterations']]for b in cal['bands']]))
    costs=[]
    for path in sorted((BASE/'quiet-reuse-cost').glob('*/receipt.json')):
        d=data(path);callbacks=d['callbacks'];costs.append(['×'.join(map(str,d['scene']['counts'])),d['reuse_capacity'],d['retention'],sum(c['work']['coarse_calls']for c in callbacks),f"{1000*statistics.median(c['work'].get('retention_seconds',0)for c in callbacks):.3f}",f"{statistics.median(f['frame_seconds']for f in d['frames']):.4f}"])
    sections.append('<p>The following are the nine serial development calibration profiles, one episode per configuration. Retention time is one measured component; full step time includes projection and all other work. These single profiles calibrate the decision rule and are separate from the three-repeat final timing.</p>'+table(['Grid','Capacity','Retention rule','Total cycles','Median retention ms','Median fluid-step seconds'],costs))
    sections.append('<h2>Fresh blind and larger-grid qualification</h2><p>Each frozen point sees the same fourteen full equations from seven scenes, with cold and later snapshots. This includes two full 256³ cubes at 16/32 cells per metre and a 256×193×129 rectangle. Inputs are streamed one full equation at a time and independently hash-checked. Every fitted contrast remains evaluated, including unselected models. All controls use the same inputs; common passage of the gates is not evidence of a unique neural coverage gain.</p>'+table(['Policy','Qualified','Median global calls','Median CNN calls','Worst pressure relative L2'],[[d['identifier'],f"{d['qualified']}/{d['cases']}",statistics.median(r['coarse_calls']for r in d['rows']),statistics.median(r['network_calls']for r in d['rows']),f"{max(r['pressure_relative_l2']for r in d['rows']):.3g}"]for d in blind]))
    paired=[r for r in data(DOCS/'scene-reservation.json')['rows']if r['trajectory_id']in ['v6-blind-02','v6-blind-03','v6-large-blind-04','v6-large-blind-05']]
    sections.append('<h2>Grid dimensions and cells per metre remain distinct</h2><p>The paired quartet shares the same forcing declaration and compares 128³ at 8/16 cells per metre with 256³ at 16/32 cells per metre. Physical extents pair at 16 m and 8 m. Every error is relative to that grid’s own discrete reference, so this is not a continuum convergence claim. Fluid mass density stays 1,000 kg/m³ and dt stays 1/60 s.</p>'+table(['Scene','Grid dimensions','Cells per metre','Physical extent metres'],[[r['trajectory_id'],'×'.join(map(str,r['scene']['counts'])),r['scene']['cells_per_metre'],'×'.join(f"{n/r['scene']['cells_per_metre']:.3g}"for n in r['scene']['counts'])]for r in paired]))
    sections.append('<h2>Repeated complete native fluid-step time</h2><p>Fifty-four episodes: six methods, three grids and three balanced-order serial repetitions. The 64³ prefix covers sixteen steps; 128³ and 256³ each cover four steps. Native preparation, pressure exchange, solver gates and projection count. GUI, teacher labels, state exports, loading and setup do not. Statistics are medians of per-run frame medians, with their observed range. Rejected attempts are visible and cannot establish usable speedups. Fresh host-process scans and all eight successful managed Runs’ drained custody precede timing.</p>'+table(['Grid','Steps/repeat','Method','Completed repeats','Median seconds/step','Observed run range','Adaptive admissions'],[['×'.join(map(str,r['counts'])),r['steps'],r['method'],f"{r['completed_repeats']}/3",f"{r['median_seconds']:.4f}",f"{r['min_seconds']:.4f}–{r['max_seconds']:.4f}",r['adaptive_admissions']]for r in native]))
    sections.append('<h2>Remaining runtime costs</h2><p>Selected fresh policy, pooling the three matched runs per grid. Native phase medians and nested callback component medians are shown separately; their medians need not sum. Network share is the sum of recorded network wall time divided by the sum of native frame time across those same attempted steps. It indicates the direct runtime headroom from cheaper inference at fixed solver work; a better correction could also reduce hierarchy work. The spectral control is qualified for this discrete operator and boundary setup; other geometries are outside this comparison.</p>'+table(['Grid','Preparation s','Pressure phase s','Projection s','Solver callback s','NN component s','Coarse component s','NN share of total time'],[['×'.join(map(str,r['counts'])),*[f"{r[k]:.4f}"for k in ['median_preparation_seconds','median_pressure_seconds','median_projection_seconds','median_callback_seconds','median_network_seconds','median_coarse_seconds']],f"{100*r['network_fraction']:.2f}%"]for r in breakdown]))
    drift_table=[]
    for d in drift:
        if not d['rows']:drift_table.append([d['trajectory'],d['policy'],0,0,'undefined','undefined','undefined']);continue
        last=d['rows'][-1];drift_table.append([d['trajectory'],d['policy'],d['matched_accepted_steps'],f"{last['time_s']:.3f}",*[f"{last[k]['relative_l2']:.3g}"if last[k]['relative_l2']is not None else'undefined'for k in ['pressure','velocity','tracer']]])
    sections.append('<h2>Long independently advanced trajectories</h2><p>Two new scenes, 64³ at 16 cells per metre and 65×49×33 at 8 cells per metre, each request 256 steps. Spectral, numerical, selected fresh, fixed-four reuse and adaptive tracks advance independently from matching initial states and forcing: ten episodes and eight drift comparisons. The fixed-four drift pair was registered as a supplemental comparison to complete the original checklist; the selected models, initial scenes and gates remain frozen. Full pressure, every staggered velocity face and tracer arrays are archived, decoded and hash-checked. Pressure gauges are removed. Curves and first-crossing diagnostics stop at matched accepted prefixes. An accepted 256-step episode covers 4.267 simulated seconds; no universal safe horizon or application acceptance limit is established.</p>'+table(['Reference scene','Candidate','Matched accepted steps','Simulated seconds','Pressure relative L2','Velocity relative L2','Tracer relative L2'],drift_table))
    peaks=[]
    for d in drift:
        values=[]
        for field in ['pressure','velocity','tracer']:
            defined=[r[field]['relative_l2']for r in d['rows']if r[field]['relative_l2']is not None]
            values.append(f'{max(defined):.3g}'if defined else'undefined')
        crossing=min((c['first_crossing_step']for field in ['pressure','velocity','tracer']for c in d['first_crossings'][field]if c['relative_l2_threshold']==1e-6 and c['first_crossing_step']is not None),default=None)
        peaks.append([d['policy'],*values,crossing if crossing is not None else'none in accepted prefix'])
    sections.append('<p>Peak errors include every recorded accepted step, rather than only the endpoint. The first-crossing column uses the smallest predeclared diagnostic level, relative L2 = 1e-6 (0.0001%), for any of the three fields. This diagnostic level is not an application acceptance limit. All predeclared first-crossing levels and undefined-relative-error cases remain in the machine-readable comparisons.</p>'+table(['Candidate','Peak pressure relative L2','Peak velocity relative L2','Peak tracer relative L2','First step above 1e-6'],peaks))
    rejected=any(d['candidate_status']!='completed'for d in drift)
    sections.append('<h2>What this supports next</h2><p>'+('At least one tested long candidate fails a pressure gate before the requested horizon. That is direct evidence to investigate solver robustness on its captured failing equation before spending on broader rollout training. The failure and matched-prefix drift remain visible.'if rejected else'Every tested long candidate reaches the requested horizon under the unchanged pressure gates. This pilot alone does not justify expensive end-to-end rollout training: application limits remain unset, and transported velocity/tracer differences must be judged alongside the numerical control and longer or harder scenes. The measured architecture, execution and reuse tradeoffs provide the next decisions; there is no general neural advantage claimed over numerical methods.')+'</p>')
    largest=next(r for r in breakdown if r['counts']==[256]*3)
    if largest['complete']:
        sections.append('<p>On the measured 256³ selected-fresh runs, neural inference accounts for '+f"{100*largest['network_fraction']:.2f}%"+' of total native frame time. '+('Further inference fusion alone therefore has limited direct whole-step headroom at fixed solver work. The higher-priority pressure experiment is to reduce the number or cost of hierarchy cycles, with any extra model expense charged to the complete solve.'if largest['network_fraction']<.1 else'Cheaper inference remains a material direct runtime opportunity, alongside reducing the number and cost of hierarchy cycles.')+' Median native preparation takes '+f"{largest['median_preparation_seconds']:.3f}"+' s and the pressure phase '+f"{largest['median_pressure_seconds']:.3f}"+' s. These measured phase costs should determine how much whole-simulation speedup to expect from another pressure-model change.</p>')
    large_group={r['method']:r for r in native if r['counts']==[256]*3 and r['completed_repeats']==3}
    if all(k in large_group for k in ['selected-fresh','baseline-v5'])and large_group['selected-fresh']['median_seconds']>=large_group['baseline-v5']['median_seconds']:
        new=large_group['selected-fresh'];old=large_group['baseline-v5']
        sections.append('<p>The smaller model regresses against the previous 648-parameter policy at 256³ despite its smaller-grid gains. Across the twelve timed steps per policy, selected / previous global-cycle counts are '+str(new['total_global_calls'])+' / '+str(old['total_global_calls'])+'. This makes larger-grid correction effectiveness a concrete next training or architecture target. A further comparison could retain the previous model’s correction quality while using its already-qualified streamed execution, or test a grid-dependent dispatch. Those would be new hypotheses requiring development calibration and fresh validation, not additional winners selected retrospectively from this blind campaign.</p>')
    figures=data(DOCS/'figure-evidence.json')
    for name in figures['names']:sections.append('<figure><img src="figures/'+html.escape(name)+'.svg" alt="'+html.escape(name)+'"><figcaption><a href="figures/'+html.escape(name)+'.pdf">Standalone PDF</a></figcaption></figure>')
    sections.append('<h2>Evidence and completion boundary</h2><p>All five requested explorations are complete and audited. Four successful fits execute 9,600 optimizer updates, plus the separately retained discarded partial attempt. One seed is used per fitted contrast. Training stops at 128³; 256³ native timing remains a bounded four-step prefix. No 512³/1024³ production qualification or application model promotion is claimed. <a href="final-audit.json">Final source, data, runtime and custody audit</a> · <a href="completion-audit.json">Five-requirement completion</a> · <a href="figure-evidence.json">Figure provenance</a> · <a href="requested-scope.txt">Original request</a> · <a href="../pressure-methods-v5/results.html">Preserved prior report</a>.</p>')
    payload=dict(status='complete',updated_utc=datetime.now(timezone.utc).isoformat(),successful_fits=4,successful_managed_runs=8,successful_optimizer_updates=9600,fits=fits,
      discarded_partial_attempt=failed,pressure_timing=timing,blind=blind,native_timing=native,runtime_breakdown=breakdown,long_drift=drift,evidence=evidence,source_sha256=sha(__file__),promotion=False)
    write(DOCS/'results.json',payload)
    body='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Pressure methods v6</title><style>body{font:16px system-ui;max-width:1450px;margin:32px auto;padding:0 24px;background:#f7fafb;color:#183744}p{line-height:1.55;max-width:1150px}table{width:100%;border-collapse:collapse;font-size:13px;margin:20px 0 36px}th,td{padding:8px;text-align:left;border-bottom:1px solid #ccd9df}th{background:#e4eef1}img{width:100%;height:auto}figure{margin:28px 0}</style><h1>Pressure methods v6: measured local correction and solver cost</h1><p>Completed five-track study. Updated '+html.escape(payload['updated_utc'])+'.</p>'+''.join(sections)+'<p><a href="results.json">Machine-readable retained results</a> · <a href="publication.json">Exact local publication fingerprints</a></p></html>'
    (DOCS/'results.html').write_text(body);print('Rendered audited final five-track report',flush=True)
if __name__=='__main__':build()
